class Solution {
    unordered_map<string, string> parent;
    string find(const string& x) {
        if (!parent.count(x)) parent[x] = x;
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(const string& x, const string& y) {
        string rx = find(x), ry = find(y);
        if (rx != ry) parent[rx] = ry;
    }
public:
    bool areSentencesSimilarTwo(vector<string>& sentence1, vector<string>& sentence2, vector<vector<string>>& similarPairs) {
        if (sentence1.size() != sentence2.size()) return false;
        for (auto& p : similarPairs) unite(p[0], p[1]);
        for (int i = 0; i < sentence1.size(); i++) {
            if (sentence1[i] != sentence2[i] && find(sentence1[i]) != find(sentence2[i])) return false;
        }
        return true;
    }
};

class Solution {
    private Map<String, String> parent = new HashMap<>();
    private String find(String x) {
        parent.putIfAbsent(x, x);
        if (!parent.get(x).equals(x)) {
            parent.put(x, find(parent.get(x)));
        }
        return parent.get(x);
    }
    private void union(String x, String y) {
        String rx = find(x), ry = find(y);
        if (!rx.equals(ry)) parent.put(rx, ry);
    }
    public boolean areSentencesSimilarTwo(String[] sentence1, String[] sentence2, List<List<String>> similarPairs) {
        if (sentence1.length != sentence2.length) return false;
        for (List<String> p : similarPairs) union(p.get(0), p.get(1));
        for (int i = 0; i < sentence1.length; i++) {
            if (!sentence1[i].equals(sentence2[i]) && !find(sentence1[i]).equals(find(sentence2[i]))) {
                return false;
            }
        }
        return true;
    }
}

var areSentencesSimilarTwo = function(sentence1, sentence2, similarPairs) {
    if (sentence1.length !== sentence2.length) return false;
    const parent = new Map();
    function find(x) {
        if (!parent.has(x)) parent.set(x, x);
        if (parent.get(x) !== x) {
            parent.set(x, find(parent.get(x)));
        }
        return parent.get(x);
    }
    function union(x, y) {
        const rx = find(x), ry = find(y);
        if (rx !== ry) parent.set(rx, ry);
    }
    for (const [u, v] of similarPairs) union(u, v);
    for (let i = 0; i < sentence1.length; i++) {
        if (sentence1[i] !== sentence2[i] && find(sentence1[i]) !== find(sentence2[i])) {
            return false;
        }
    }
    return true;
};
